// Install: npm install simple-peer socket.io-client

// src/components/CallPage.jsx
import React, { useEffect, useState } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { io } from 'socket.io-client';
import UserList from './UserList';
import VideoCallModal from './VideoCallModal';

export default function CallPage() {
  const { user, loading } = useAuth();
  const [socket, setSocket] = useState(null);
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [callData, setCallData] = useState(null); // { to, from, type }

  useEffect(() => {
    if (!user) return;
    const s = io('http://localhost:5000', { withCredentials: true });
    setSocket(s);

    s.on('connect', () => {
      s.emit('join', user.id);
    });

    s.on('user_online', setOnlineUsers);
    s.on('incoming_call', data => setCallData({ ...data, incoming: true }));

    return () => {
      s.disconnect();
      setSocket(null);
    };
  }, [user]);

  if (loading || !socket) return <p>Loading...</p>;

  return (
    <div className="p-6">
      <h2 className="text-2xl font-bold mb-4">Start a Call</h2>
      <UserList
        users={onlineUsers.filter(id => id !== user.id)} // exclude self
        onCall={peerId => {
          setCallData({ to: peerId, from: user.id, incoming: false });
        }}
      />

      {callData && (
        <VideoCallModal
          socket={socket}
          user={user}
          callData={callData}
          onClose={() => setCallData(null)}
        />
      )}
    </div>
  );
}

// src/components/UserList.jsx
import React from 'react';
export default function UserList({ users, onCall }) {
  return (
    <ul className="space-y-3">
      {users.map(u => (
        <li key={u.id} className="flex justify-between items-center bg-gray-200 p-4 rounded">
          <span>{u.username}</span>
          <button
            onClick={() => onCall(u.id)}
            className="px-3 py-1 bg-blue-600 text-white rounded"
          >
            Call
          </button>
        </li>
      ))}
    </ul>
  );
}

// src/components/VideoCallModal.jsx
import React, { useEffect, useRef, useState } from 'react';
import Peer from 'simple-peer';

export default function VideoCallModal({ socket, user, callData, onClose }) {
  const localRef = useRef();
  const remoteRef = useRef();
  const peerRef = useRef();
  const [stream, setStream] = useState(null);
  const [status, setStatus] = useState(callData.incoming ? 'incoming' : 'calling');

  useEffect(() => {
    async function setup() {
      // get media
      const micStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: callData.type === 'video' });
      setStream(micStream);
      localRef.current.srcObject = micStream;

      const peer = new Peer({ initiator: !callData.incoming, trickle: false, stream: micStream });
      peerRef.current = peer;

      peer.on('signal', signal => {
        socket.emit(callData.incoming ? 'answer_call' : 'call_user', {
          to: callData.incoming ? callData.from : callData.to,
          signal,
        });
      });

      peer.on('stream', remoteStream => {
        remoteRef.current.srcObject = remoteStream;
      });

      socket.on('incoming_call', ({ signal }) => {
        peer.signal(signal);
        setStatus('in_call');
      });

      socket.on('call_accepted', ({ signal }) => {
        peer.signal(signal);
        setStatus('in_call');
      });

      return () => {
        peer.destroy();
        micStream.getTracks().forEach(t => t.stop());
      };
    }

    setup();
  }, []);

  return (
    <div className="fixed inset-0 bg-black bg-opacity-70 flex flex-col items-center justify-center">
      <div className="bg-white p-4 rounded">
        <div className="flex gap-4">
          <video ref={localRef} autoPlay muted className="w-32 h-32 bg-black" />
          <video ref={remoteRef} autoPlay className="w-32 h-32 bg-black" />
        </div>
        <div className="mt-4 flex justify-end gap-2">
          <button onClick={onClose} className="px-3 py-1 bg-red-500 text-white rounded">Hang Up</button>
        </div>
      </div>
    </div>
  );
}
